/**
 * The whole thread for one issue, in reading order: top-level comments oldest
 * first, each followed by every reply that descends from it, however deep the
 * chain, in posting order. A deleted comment keeps its place as a placeholder
 * (see `toComment`/`isArchived`) so replies beneath it are never orphaned.
 */
export async function listThread(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly CommentThreadNode[]> {
  const rows = getDb()
    .select({ comment: comments, author: users })
    .from(comments)
    .innerJoin(users, eq(users.id, comments.authorId))
    .where(
      and(
        orgPredicate(comments.orgId, orgId),
        eq(comments.issueId, issueId),
      ),
    )
    .orderBy(asc(comments.createdAt))
    .all();

  const decorated: CommentWithAuthor[] = rows.map((row) => ({
    ...toComment(row.comment),
    author: toUser(row.author),
  }));

  const childrenOf = new Map<string, CommentWithAuthor[]>();
  for (const comment of decorated) {
    if (comment.parentId === null) continue;
    const bucket = childrenOf.get(comment.parentId) ?? [];
    bucket.push(comment);
    childrenOf.set(comment.parentId, bucket);
  }

  function descendantIdsOf(rootId: string): Set<string> {
    const ids = new Set<string>();
    const queue = [rootId];
    while (queue.length > 0) {
      const current = queue.shift();
      if (current === undefined) continue;
      for (const child of childrenOf.get(current) ?? []) {
        if (ids.has(child.id)) continue;
        ids.add(child.id);
        queue.push(child.id);
      }
    }
    return ids;
  }

  return decorated
    .filter((comment) => comment.parentId === null)
    .map((comment) => {
      const descendantIds = descendantIdsOf(comment.id);
      return {
        comment,
        replies: decorated.filter((candidate) => descendantIds.has(candidate.id)),
      };
    });
}

