input.new_string:
function isPastEditWindow(comment: Comment): boolean {
  // Counted from the original posting, never from an edit — otherwise one
  // edit inside the window would reopen a fresh fifteen minutes forever.
  const posted = new Date(comment.createdAt).getTime();
  return Date.now() - posted > EDIT_WINDOW_MS;
}

/**
 * Every active member of the org, paged through in full — mentions must
 * resolve against the whole membership, not just the first page, however
 * large the org is.
 */
async function listAllMembers(orgId: OrgId): Promise<readonly MemberWithUser[]> {
  const members: MemberWithUser[] = [];
  let cursor: string | null = null;

  for (;;) {
    const page = await memberRepo.listMembers({
      orgId,
      limit: MENTION_LOOKUP_LIMIT,
      cursor,
    });
    members.push(...page.items);
    if (page.nextCursor === null) break;
    cursor = page.nextCursor;
  }

  return members;
}

/**
 * Union of the ids the client already resolved (optimistic UI) and the ones
 * parsed out of the body server-side. The server list wins on disagreement.
 * The comment's own author is never recorded as mentioning themselves, even
 * if their handle appears in the body.
 */
async function resolveMentionedUsers(
  orgId: OrgId,
  body: string,
  clientProvided: readonly UserId[],
  authorId: UserId,
): Promise<readonly UserId[]> {
  const members = await listAllMembers(orgId);

  const resolved = resolveMentions(body, members);
  const known = new Set(members.map((member) => member.userId));

  return [
    ...new Set([...resolved, ...clientProvided.filter((id) => known.has(id))]),
  ].filter((id) => id !== authorId);
}

