1	/**
2	 * Comment creation, edit window enforcement, mention extraction and soft delete.
3	 *
4	 * Must call (do not reimplement): assertCan, assertOrgScope, emit, archivePatch, consumeRateLimit
5	 */
6	import { emit } from "@/lib/event-bus";
7	import { resolveMentions } from "@/lib/mentions";
8	import { assertCan } from "@/lib/permissions";
9	import { consumeRateLimit } from "@/lib/rate-limit";
10	import { archivePatch, assertNotArchived } from "@/lib/soft-delete";
11	import { assertOrgScope } from "@/lib/tenant";
12	import * as commentRepo from "@/server/repositories/comment-repository";
13	import * as issueRepo from "@/server/repositories/issue-repository";
14	import * as memberRepo from "@/server/repositories/member-repository";
15	import {
16	  actorEnvelope,
17	  commentResource,
18	  issueResource,
19	  requireFound,
20	} from "./_support";
21	import type {
22	  CreateCommentInput,
23	  DeleteCommentInput,
24	  UpdateCommentInput,
25	} from "@/schemas/comment";
26	import type { Comment, CommentThreadNode } from "@/types/comment";
27	import type { IssueId, OrgId, UserId } from "@/types/common";
28	import type { Actor, MemberWithUser } from "@/types/member";
29	
30	/** How long after posting an author may still edit their own comment. */
31	const EDIT_WINDOW_MS = 15 * 60 * 1000;
32	
33	/** How many members are scanned when resolving `@handle` mentions. */
34	const MENTION_LOOKUP_LIMIT = 100;
35	
36	/** Token bucket protecting the comment thread from burst posting. */
37	const COMMENT_CREATE_BUCKET = "comment:create";
38	
39	/**
40	 * Posts a comment on a live issue. Mentions written as `@handle` in the body
41	 * are resolved against the org's members here, so the stored row and the
42	 * `comment.created` payload agree on who was mentioned — the notification
43	 * fan-out reads that list rather than re-parsing the markdown.
44	 */
45	export async function createComment(
46	  actor: Actor,
47	  input: CreateCommentInput,
48	): Promise<Comment> {
49	  assertOrgScope(actor, input.orgId);
50	
51	  const issue = requireFound(
52	    await issueRepo.findIssueById(input.orgId, input.issueId),
53	    "Issue",
54	    input.issueId,
55	  );
56	  assertCan(actor, "comment:create", issueResource(issue));
57	  assertNotArchived("Issue", issue.id, issue);
58	
59	  const verdict = await consumeRateLimit(
60	    input.orgId,
61	    COMMENT_CREATE_BUCKET,
62	    1,
63	    actor.userId,
64	  );
65	  if (!verdict.allowed) {
66	    throw new Error(
67	      `Comment rate limit reached; try again after ${verdict.resetAt}`,
68	    );
69	  }
70	
71	  const mentionedUserIds = await resolveMentionedUsers(
72	    input.orgId,
73	    input.body,
74	    input.mentionedUserIds,
75	    actor.userId,
76	  );
77	
78	  const comment = await commentRepo.insertComment(
79	    { ...input, mentionedUserIds: [...mentionedUserIds] },
80	    actor.userId,
81	  );
82	
83	  await emit("comment.created", {
84	    ...actorEnvelope(actor),
85	    commentId: comment.id,
86	    issueId: comment.issueId,
87	    mentionedUserIds,
88	  });
89	
90	  return comment;
91	}
92	
93	/**
94	 * Edits are allowed inside a fifteen-minute window, or by anyone the role
95	 * matrix already lets update a comment. `can()` decides the second half —
96	 * this service only owns the time window.
97	 *
98	 * The edit re-reads mentions from the new body: the stored list becomes
99	 * exactly what the new text mentions, and `comment.updated` carries only the
100	 * newly-mentioned ids so the fan-out alerts them once without re-alerting
101	 * whoever was already mentioned.
102	 */
103	export async function updateComment(
104	  actor: Actor,
105	  input: UpdateCommentInput,
106	): Promise<Comment> {
107	  assertOrgScope(actor, input.orgId);
108	
109	  const comment = requireFound(
110	    await commentRepo.findCommentById(input.orgId, input.commentId),
111	    "Comment",
112	    input.commentId,
113	  );
114	  assertCan(actor, "comment:update", commentResource(comment));
115	  assertNotArchived("Comment", comment.id, comment);
116	
117	  if (comment.authorId === actor.userId && isPastEditWindow(comment)) {
118	    throw new Error("The edit window for this comment has closed");
119	  }
120	
121	  const mentionedUserIds = await resolveMentionedUsers(
122	    input.orgId,
123	    input.body,
124	    [],
125	    comment.authorId,
126	  );
127	
128	  const updated = await commentRepo.updateComment(input, mentionedUserIds);
129	
130	  const previouslyMentioned = new Set(comment.mentionedUserIds);
131	  const newlyMentionedUserIds = mentionedUserIds.filter(
132	    (userId) => !previouslyMentioned.has(userId),
133	  );
134	
135	  await emit("comment.updated", {
136	    ...actorEnvelope(actor),
137	    commentId: updated.id,
138	    issueId: updated.issueId,
139	    mentionedUserIds,
140	    newlyMentionedUserIds,
141	  });
142	
143	  return updated;
144	}
145	
146	/**
147	 * Deletion is soft: the row keeps its place so replies below it still have an
148	 * anchor. `archivePatch()` is what the repository writes; asking for it here
149	 * documents that this service deliberately never issues a hard delete.
150	 */
151	export async function deleteComment(
152	  actor: Actor,
153	  input: DeleteCommentInput,
154	): Promise<Comment> {
155	  assertOrgScope(actor, input.orgId);
156	
157	  const comment = requireFound(
158	    await commentRepo.findCommentById(input.orgId, input.commentId),
159	    "Comment",
160	    input.commentId,
161	  );
162	  assertCan(actor, "comment:delete", commentResource(comment));
163	  assertNotArchived("Comment", comment.id, comment);
164	
165	  const { archivedAt } = archivePatch();
166	  const archived = await commentRepo.archiveComment(
167	    input.orgId,
168	    input.commentId,
169	  );
170	
171	  await emit("comment.deleted", {
172	    ...actorEnvelope(actor),
173	    occurredAt: archivedAt,
174	    commentId: archived.id,
175	    issueId: archived.issueId,
176	  });
177	
178	  return archived;
179	}
180	
181	export async function getThread(
182	  actor: Actor,
183	  orgId: OrgId,
184	  issueId: IssueId,
185	): Promise<readonly CommentThreadNode[]> {
186	  assertOrgScope(actor, orgId);
187	
188	  const issue = requireFound(
189	    await issueRepo.findIssueById(orgId, issueId),
190	    "Issue",
191	    issueId,
192	  );
193	  assertCan(actor, "comment:read", issueResource(issue));
194	
195	  return commentRepo.listThread(orgId, issueId);
196	}
197	
198	function isPastEditWindow(comment: Comment): boolean {
199	  // Counted from the original posting, never from an edit — otherwise one
200	  // edit inside the window would reopen a fresh fifteen minutes forever.
201	  const posted = new Date(comment.createdAt).getTime();
202	  return Date.now() - posted > EDIT_WINDOW_MS;
203	}
204	
205	/**
206	 * Every active member of the org, paged through in full — mentions must
207	 * resolve against the whole membership, not just the first page, however
208	 * large the org is.
209	 */
210	async function listAllMembers(orgId: OrgId): Promise<readonly MemberWithUser[]> {
211	  const members: MemberWithUser[] = [];
212	  let cursor: string | null = null;
213	
214	  for (;;) {
215	    const page = await memberRepo.listMembers({
216	      orgId,
217	      limit: MENTION_LOOKUP_LIMIT,
218	      cursor,
219	    });
220	    members.push(...page.items);
221	    if (page.nextCursor === null) break;
222	    cursor = page.nextCursor;
223	  }
224	
225	  return members;
226	}
227	
228	/**
229	 * Union of the ids the client already resolved (optimistic UI) and the ones
230	 * parsed out of the body server-side. The server list wins on disagreement.
231	 * The comment's own author is never recorded as mentioning themselves, even
232	 * if their handle appears in the body.
233	 */
234	async function resolveMentionedUsers(
235	  orgId: OrgId,
236	  body: string,
237	  clientProvided: readonly UserId[],
238	  authorId: UserId,
239	): Promise<readonly UserId[]> {
240	  const members = await listAllMembers(orgId);
241	
242	  const resolved = resolveMentions(body, members);
243	  const known = new Set(members.map((member) => member.userId));
244	
245	  return [
246	    ...new Set([...resolved, ...clientProvided.filter((id) => known.has(id))]),
247	  ].filter((id) => id !== authorId);
248	}
